package slicefn

import "testing"

func TestFilterEvens(t *testing.T) {
	nums := []int{1, 2, 3, 4, 5, 6}
	result := Filter(nums, func(n int) bool { return n%2 == 0 })
	if len(result) != 3 || result[0] != 2 || result[1] != 4 || result[2] != 6 {
		t.Fatalf("want [2 4 6], got %v", result)
	}
}

func TestMapDouble(t *testing.T) {
	nums := []int{1, 2, 3}
	result := Map(nums, func(n int) int { return n * 2 })
	if len(result) != 3 || result[0] != 2 || result[1] != 4 || result[2] != 6 {
		t.Fatalf("want [2 4 6], got %v", result)
	}
}

func TestMapToString(t *testing.T) {
	nums := []int{1, 2, 3}
	result := Map(nums, func(n int) string {
		if n%2 == 0 {
			return "even"
		}
		return "odd"
	})
	if result[0] != "odd" || result[1] != "even" || result[2] != "odd" {
		t.Fatalf("want [odd even odd], got %v", result)
	}
}

func TestReduceSum(t *testing.T) {
	nums := []int{1, 2, 3, 4, 5}
	result := Reduce(nums, 0, func(acc, n int) int { return acc + n })
	if result != 15 {
		t.Fatalf("want 15, got %d", result)
	}
}

func TestReduceProduct(t *testing.T) {
	nums := []int{1, 2, 3, 4}
	result := Reduce(nums, 1, func(acc, n int) int { return acc * n })
	if result != 24 {
		t.Fatalf("want 24, got %d", result)
	}
}

